from collections import deque
import time

class InMemorySlidingWindowLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window = window_seconds
        self.hits: dict[str, deque[float]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        q = self.hits.setdefault(client_id, deque())
        while q and now - q[0] > self.window:
            q.popleft()
        if len(q) >= self.max_requests:
            return False
        q.append(now)
        return True

import asyncio
import random
from typing import Callable, TypeVar, Awaitable

T = TypeVar('T')

async def retry_with_full_jitter(
    fn: Callable[[], Awaitable[T]],
    max_attempts: int = 5,
    base_delay: float = 0.2,
    cap_delay: float = 10.0,
) -> T:
    for attempt in range(max_attempts):
        try:
            return await fn()
        except (TimeoutError, ConnectionError):
            if attempt == max_attempts - 1:
                raise
            ceiling = min(cap_delay, base_delay * (2 ** attempt))
            await asyncio.sleep(random.uniform(0, ceiling))

import time
import functools

def fixed_retry(retries: int = 3, delay_sec: float = 1.0):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_err = None
            for _ in range(retries):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    last_err = exc
                    time.sleep(delay_sec)
            raise last_err
        return wrapper
    return decorator

def reciprocal_rank_fusion(ranked_lists: list[list[str]], k: int = 60, top_n: int = 10) -> list[tuple[str, float]]:
    scores: dict[str, float] = {}
    for ranking in ranked_lists:
        for rank_idx, doc_id in enumerate(ranking, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank_idx)
    return sorted(scores.items(), key=lambda item: item[1], reverse=True)[:top_n]

def linear_score_merge(bm25_scores: dict[str, float], dense_scores: dict[str, float], alpha: float = 0.5) -> list[str]:
    def norm(d: dict[str, float]) -> dict[str, float]:
        if not d: return {}
        lo, hi = min(d.values()), max(d.values())
        span = (hi - lo) or 1.0
        return {k: (v - lo) / span for k, v in d.items()}
    nb, nd = norm(bm25_scores), norm(dense_scores)
    keys = set(nb) | set(nd)
    combined = {k: alpha * nb.get(k, 0.0) + (1 - alpha) * nd.get(k, 0.0) for k in keys}
    return sorted(combined, key=combined.get, reverse=True)

import json
from typing import Iterator

def iter_sse_deltas(byte_lines: Iterator[bytes]) -> Iterator[str]:
    for raw in byte_lines:
        line = raw.decode('utf-8', errors='replace').strip()
        if not line or line.startswith(':') or not line.startswith('data:'):
            continue
        payload = line[5:].strip()
        if payload == '[DONE]':
            break
        chunk = json.loads(payload)
        choices = chunk.get('choices') or []
        if choices:
            delta = choices[0].get('delta', {}).get('content')
            if delta:
                yield delta

import asyncio

class WebSocketHub:
    def __init__(self):
        self.connections: set = set()

    async def broadcast_json(self, message: str) -> None:
        dead = set()
        for ws in list(self.connections):
            try:
                await ws.send_str(message)
            except Exception:
                dead.add(ws)
        self.connections -= dead

def split_text_sliding_window(text: str, chunk_size: int = 800, overlap: int = 120) -> list[str]:
    if chunk_size <= overlap:
        raise ValueError('chunk_size must be greater than overlap')
    step = chunk_size - overlap
    return [text[i : i + chunk_size] for i in range(0, max(1, len(text)), step)]

import hmac
import hashlib

def verify_webhook_signature(payload_bytes: bytes, header_sig: str, secret: str) -> bool:
    if not header_sig.startswith('sha256='):
        return False
    expected = hmac.new(secret.encode('utf-8'), payload_bytes, hashlib.sha256).hexdigest()
    provided = header_sig.split('=', 1)[1].strip()
    return hmac.compare_digest(expected, provided)

import base64
import json

def peek_jwt_claims_unverified(token: str) -> dict:
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError('Malformed JWT')
    padded = parts[1] + '=' * (-len(parts[1]) % 4)
    return json.loads(base64.urlsafe_b64decode(padded.encode('ascii')))

import time

class CircuitBreaker:
    def __init__(self, failure_threshold: int = 5, recovery_timeout: float = 30.0):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.failures = 0
        self.opened_at: float | None = None

    def allow_request(self) -> bool:
        if self.opened_at is None:
            return True
        if time.monotonic() - self.opened_at >= self.recovery_timeout:
            return True  # half-open probe
        return False

    def record_success(self) -> None:
        self.failures = 0
        self.opened_at = None

    def record_failure(self) -> None:
        self.failures += 1
        if self.failures >= self.failure_threshold:
            self.opened_at = time.monotonic()

import re

CF_PATTERN = re.compile(r'\b[A-Z]{6}\d{2}[A-Z]\d{2}[A-Z]\d{3}[A-Z]\b', re.IGNORECASE)
IBAN_PATTERN = re.compile(r'\bIT\d{2}[A-Z]\d{10}[0-9A-Z]{12}\b', re.IGNORECASE)

def redact_italian_pii(text: str) -> str:
    redacted = CF_PATTERN.sub('[REDACTED_CF]', text)
    return IBAN_PATTERN.sub('[REDACTED_IBAN]', redacted)
